```swift
// Define your campaign materials as an array of dictionaries
let campaignMaterials = [
    "speech1": {
        "title": "Winning Strategies",
        "content": "Learn how to win elections and get elected.",
        "imageURL": "https://example.com/speech1.jpg"
    },
    "speech2": {
        "title": "Election Day Strategy",
        "content": "Get ready for election day with our expert advice.",
        "imageURL": "https://example.com/speech2.jpg"
    }
]

// Create a new instance of the `Campaign` class
class Campaign {
    var title: String
    var content: String
    var imageURL: String

    init(title: String, content: String, imageURL: String) {
        self.title = title
        self.content = content
        self.imageURL = imageURL
    }

    func print() {
        print("Title: \(title)")
        print("Content: \(content)")
        print("Image URL: \(imageURL)")
    }
}

// Loop through each campaign material and print it out
for (materialName, material) in campaignMaterials {
    let campaign = Campaign(title: materialName, content: material["content"]!, imageURL: material["imageURL"]!)
    campaign.print()
}
```

